function syncToolbar(){const style=sheet().cells[address(selection.r,selection.c)]?.style||{};for(const k of ['bold','italic','underline'])document.querySelector(`[data-action="${k}"]`)?.classList.toggle('active',!!style[k]);if($('#font-size'))$('#font-size').value=style.fontSize||11;if($('#font-family'))$('#font-family').value=style.fontFamily||'맑은 고딕';if($('#number-format'))$('#number-format').value=style.format||'general';}
