$('#editor').addEventListener('input',()=>$('#formula').value=$('#editor').value);$('#editor').addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Enter'){e.preventDefault();commitEdit(e.shiftKey?'up':'down');}else if(e.key==='Tab'){e.preventDefault();commitEdit(e.shiftKey?'left':'right');}else if(e.key==='Escape'){e.preventDefault();cancelEdit();}});
$('#formula').addEventListener('focus',()=>{if(sheet().pivot)return;if(!editing){editing=true;$('#editor').value=$('#formula').value;}});$('#formula').addEventListener('input',()=>{$('#editor').value=$('#formula').value;});$('#formula').addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Enter'){e.preventDefault();commitEdit('down');}else if(e.key==='Escape'){e.preventDefault();cancelEdit();}});
$('#name-box').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();try{const [a,b]=e.target.value.toUpperCase().replace(/\$/g,'').split(':').map(parseAddress);if(!a||a.r>=MAX_ROWS||a.c>=MAX_COLS)throw Error();commitEdit();select(a.r,a.c,false,true);if(b){selection.r2=b.r;selection.c2=b.c;render();}$('#grid').focus();}catch{toast('올바른 주소를 입력하세요. 예: A1 또는 A1:C10');}}});
$('#book-title').addEventListener('change',e=>{checkpoint();book.name=e.target.value.trim()||'통합 문서';changed();});$('#zoom').addEventListener('input',e=>setZoom(+e.target.value));
$('#ribbon').addEventListener('change',e=>{const id=e.target.id;if(id==='font-family')applyStyle({fontFamily:e.target.value});if(id==='font-size')applyStyle({fontSize:+e.target.value});if(id==='number-format')applyStyle({format:e.target.value});if(id==='fill-color')applyStyle({background:e.target.value});if(id==='text-color')applyStyle({color:e.target.value});});
$('#file-input').addEventListener('change',async e=>{const file=e.target.files[0];if(file)await importFile(new Uint8Array(await file.arrayBuffer()),file.name);e.target.value='';});
document.addEventListener('paste',e=>{if(document.activeElement!==$('#grid'))return;e.preventDefault();pasteText(e.clipboardData.getData('text/plain'));});
window.desktop?.onMenuAction?.(name=>{
 const input=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);
 if(input&&['undo','redo','cut','copy','paste','select-all'].includes(name)){window.desktop.editText(name);return;}
 if($('.backdrop')||$('.vba-overlay'))return;
 if(name==='paste'){$('#grid').focus();window.desktop.editText('paste');return;}
 action(name);
});
document.addEventListener('keydown',e=>{if(e.defaultPrevented||e.isComposing||$('.backdrop')||$('.vba-overlay'))return;const input=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);const ctrl=e.ctrlKey||e.metaKey;if(ctrl&&['s','o'].includes(e.key.toLowerCase())){e.preventDefault();action(e.key.toLowerCase()==='s'?'save':'open');return;}if(input)return;if(ctrl){const key=e.key.toLowerCase(),map={z:e.shiftKey?'redo':'undo',y:'redo',c:'copy',x:'cut',b:'bold',i:'italic',u:'underline',f:'find',d:'fill-down',a:'select-all',n:'new'};if(map[key]){e.preventDefault();action(map[key]);return;}}
 if(document.activeElement!==$('#grid'))return;const moves={ArrowDown:[1,0],ArrowUp:[-1,0],ArrowLeft:[0,-1],ArrowRight:[0,1],Enter:[e.shiftKey?-1:1,0],Tab:[0,e.shiftKey?-1:1],PageDown:[Math.floor($('#grid').clientHeight/(25*zoom/100))-1,0],PageUp:[-Math.floor($('#grid').clientHeight/(25*zoom/100))+1,0]};if(moves[e.key]){e.preventDefault();const [dr,dc]=moves[e.key],r=e.shiftKey&&e.key.startsWith('Arrow')?selection.r2:selection.r,c=e.shiftKey&&e.key.startsWith('Arrow')?selection.c2:selection.c;if(ctrl&&e.key.startsWith('Arrow')){const u=usedBounds();select(dr>0?u.r:dr<0?0:r,dc>0?u.c:dc<0?0:c,e.shiftKey,true);}else select(r+dr,c+dc,e.shiftKey&&e.key.startsWith('Arrow'),true);}else if(e.key==='Home'){e.preventDefault();select(ctrl?0:selection.r,0,e.shiftKey,true);}else if(e.key==='End'){e.preventDefault();const u=usedBounds();select(u.r,u.c,e.shiftKey,true);}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();setRaw('');}else if(e.key==='F2'){e.preventDefault();startEdit();}else if(e.key.length===1&&!ctrl&&!e.altKey){e.preventDefault();startEdit(e.key);}});
$('#grid').addEventListener('compositionstart',()=>{if(!editing)startEdit('');});
function confirmMacroExport(format){modal('매크로를 제외한 사본', '<p>이 형식에는 VBA 프로젝트와 Excel 전용 개체가 포함되지 않습니다. 매크로를 유지하려면 XLSM 저장을 사용하세요.</p>',[{label:'사본 내보내기',primary:true,action:el=>{el.remove();save(format,true);}}]);}

function pivotLocked(){if(!sheet().pivot)return false;toast('피벗 결과는 원본을 수정하고 새로 고침하세요. 직접 편집하려면 일반 범위로 변환하세요.');return true;}
function renderPivotBar(){const bar=$('#pivot-bar');if(!bar)return;bar.hidden=!sheet().pivot;$('#formula').readOnly=!!sheet().pivot;document.querySelector('.fill-handle').hidden=!!sheet().pivot;if(!sheet().pivot){bar.innerHTML='';return;}const spec=sheet().pivot,source=book.sheets.find(s=>s.id===spec.sourceSheetId);bar.innerHTML='<strong>피벗테이블</strong><span>'+esc(source?.name||'원본 없음')+' · '+esc(spec.sourceRange)+'</span>'+btn('pivot','필드 편집','table')+btn('pivot-refresh','새로 고침','redo')+btn('pivot-source','원본 보기','open')+btn('pivot-convert','일반 범위로 변환','grid');}
const pivotUI=createPivotUI({getWorkbook:()=>book,getSheet:sheet,getRange:()=>{const b=bounds();if(b.r1!==b.r2||b.c1!==b.c2)return rangeLabel();const u=usedBounds();return 'A1:'+address(u.r,u.c);},checkpoint,changed,switchSheet,modal,toast});
const vbaUI=createVbaUI({getWorkbook:()=>book,commitEdit,toast,replaceWorkbook:loaded=>{checkpoint();book=loaded;switchSheet(book.activeSheetId);}});
renderPivotBar();renderRibbon();makeLayout();renderSheets();updateTitle();render();$('#grid').focus();
globalThis.sheetStudio={getWorkbook:()=>structuredClone(book),select:(r,c,r2=r,c2=c)=>{selection={r,c,r2,c2};ensureVisible(r,c);render();},evaluate:(addr)=>evaluateCell(book,sheet().id,addr)};
